import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"安全与权限","description":"","frontmatter":{"title":"安全与权限"},"headers":[],"relativePath":"zh/guide/security.md","filePath":"zh/guide/security.md","lastUpdated":0}`),a={name:`zh/guide/security.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_12-安全与权限" tabindex="-1">12. 安全与权限 <a class="header-anchor" href="#_12-安全与权限" aria-label="Permalink to “12. 安全与权限”">​</a></h1><h2 id="_12-1-最小权限" tabindex="-1">12.1 最小权限 <a class="header-anchor" href="#_12-1-最小权限" aria-label="Permalink to “12.1 最小权限”">​</a></h2><p>Custos 可能需要管理服务、网络和系统进程，因此必须明确区分：</p><ul><li>只读探测权限。</li><li>普通恢复权限。</li><li>网络配置权限。</li><li>服务管理权限。</li><li>系统重启权限。</li><li>通知发送权限。</li></ul><p>不能为了方便而让所有插件默认拥有完整系统权限。</p><h2 id="_12-2-高风险动作" tabindex="-1">12.2 高风险动作 <a class="header-anchor" href="#_12-2-高风险动作" aria-label="Permalink to “12.2 高风险动作”">​</a></h2><p>高风险动作包括：</p><ul><li>重置网络接口。</li><li>修改路由表。</li><li>修改防火墙。</li><li>切换代理配置。</li><li>重启整台设备。</li><li>修改认证信息。</li></ul><p>每个动作必须具有：</p><ul><li>风险声明。</li><li>权限要求。</li><li>作用范围。</li><li>超时。</li><li>并发控制。</li><li>结果验证。</li><li>失败处理。</li><li>可选回滚或补偿。</li></ul><p>第一版可以由管理员在配置中显式允许高风险动作。</p><h2 id="_12-3-网络中断恢复安全" tabindex="-1">12.3 网络中断恢复安全 <a class="header-anchor" href="#_12-3-网络中断恢复安全" aria-label="Permalink to “12.3 网络中断恢复安全”">​</a></h2><p>恢复网络时必须特别谨慎：</p><ul><li>不因代理故障直接认定底层网络故障。</li><li>不因 HTTP 407 认定代理宕机。</li><li>不将所有连接超时归因于 DNS。</li><li>不在依赖状态未知时盲目重置网络。</li><li>不连续重复重启网络接口。</li><li>不把远程管理通道中断当作无限重试的理由。</li></ul><p>当证据不足时，应记录原因并升级告警，而不是尝试所有恢复动作。</p><hr>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};